  function cards(list){return `<div class="universe-grid">${list.map(f=>{const locked=!unlocked(f.id);return `<button class="universe-card ${locked?'is-locked':'is-unlocked'}" data-action="franchise" data-id="${safe(f.id)}" aria-label="${safe(f.name)}: ${locked?'bloqueado':'liberado'}"><div class="universe-media"><img loading="lazy" src="${f.art}" alt="Capa ${safe(f.name)}">${f.id==='cinelove'?`<span class="cdg-package-new">Novo</span>`:''}${locked?`<div class="card-lock-overlay"><div class="card-lock-badge">${solidLock()}<span>Bloqueado</span></div></div>`:''}</div><div class="cdg-package-name">${locked?solidLock('small-lock'):''}<span>${safe(f.name)}</span></div></button>`}).join('')}</div>`}
  function block(title,sub=''){return `<h1 class="page-title">${title}</h1>${sub?`<p class="page-subtitle">${sub}</p>`:''}<div class="title-underline"></div>`}
  function title(text,target=''){return `<div class="section-heading"><h2>${text}</h2>${target?`<button class="view-all" data-action="nav" data-view="${target}">Ver todos ${I('chevron','sm')}</button>`:''}</div>`}
