  function heroMarkup(isBarbieCatalog=false,forcedSlideId=null){
    const slide=forcedSlideId ? heroSlides.find(item=>item.id===forcedSlideId) : (isBarbieCatalog ? heroSlides.find(item=>item.id==='barbie') : homeHeroSlides[heroIndex]);
    const currentIndex=isBarbieCatalog ? heroSlides.findIndex(item=>item.id==='barbie') : heroIndex;
    const kind=slide.id==='cinelove'?'Filmes':slide.id==='noite-das-girls'?'Promoção especial':slide.id==='barbie'?'Filme':['moranguinho','disney'].includes(slide.id)?'Pacote':slide.id==='winx'?'Série':'Pacote';
    const fullTitle=[slide.heading,slide.subtitle].filter(Boolean).join(' ');
    const arrows=(isBarbieCatalog||forcedSlideId)?'':`<div class="home-carousel-arrows" role="group" aria-label="Navegar pelos destaques">
        <button type="button" class="banner-arrow banner-arrow-prev" data-action="hero-prev" aria-label="Destaque anterior">${I('chevron','sm')}</button>
        <button type="button" class="banner-arrow banner-arrow-next" data-action="hero-next" aria-label="Próximo destaque">${I('chevron','sm')}</button>
      </div>`;
    if(slide.id==='black-friday')return `<section class="cdg-blackfriday-banner" aria-label="Esquenta Black Friday — Pacote Divônico"><img src="${slide.picture}" alt="Esquenta Black Friday Pacote Divônico: escolha 3 pacotes" fetchpriority="high" decoding="async"><a class="cdg-blackfriday-cta" href="https://pay.lowify.com.br/checkout?product_id=dmqB2Y" target="_blank" rel="noopener noreferrer">GARANTIR ACESSO</a>${arrows}</section>`;
    const dots=(isBarbieCatalog||forcedSlideId)?'':`<div class="hero-dots" role="group" aria-label="Escolher destaque">${homeHeroSlides.map((item,i)=>`<button type="button" class="hero-dot ${i===currentIndex?'active':''}" data-action="hero-slide" data-slide="${i}" aria-label="Ver destaque ${i+1}: ${safe(item.heading+' '+item.subtitle)}" aria-pressed="${i===currentIndex}"></button>`).join('')}</div>`;
    const cine=slide.id==='cinelove';
    const photo=['moranguinho','disney'].includes(slide.id)?`<img class="feature-full-photo" src="${slide.picture}" alt="Banner ${safe(fullTitle)}" loading="eager" fetchpriority="high" decoding="async"><div class="feature-full-wash" aria-hidden="true"></div>`:slide.id==='noite-das-girls'?`<img class="night-hero-photo" src="${slide.picture}" alt="Noite das Girls: Harry Potter, terror, romance e animações" loading="eager" fetchpriority="high" decoding="async"><div class="night-hero-wash"></div>`:
                    cine?`<img class="cinelove-photo" src="${slide.picture}" alt="Arte de CineLove" loading="eager" fetchpriority="high" decoding="async"><div class="cinelove-wash" aria-hidden="true"></div>`
                    :`<img class="${slide.id==='barbie'?'hero-art':'hero-art hero-art-cover'}" src="${slide.picture}" alt="Arte de ${safe(fullTitle)}" loading="eager" fetchpriority="high" decoding="async">`;
    const checkoutSlide=['disney','moranguinho'].includes(slide.id)?el(slide.id):null;
    const cta=checkoutSlide?`<a class="home-hero-cta" href="${safe(checkoutSlide.checkout)}" target="_blank" rel="noopener noreferrer">${I('play','sm')} Garantir acesso</a>`:`<button class="home-hero-cta" type="button" data-action="franchise" data-id="${slide.id}">${I('play','sm')} Garantir acesso</button>`;
    return `<section class="hero hero-${slide.theme} home-uniform-hero" aria-roledescription="slide" aria-label="Destaque ${safe(fullTitle)}">
      ${photo}
      <div class="hero-content home-hero-content">
        <span class="hero-type">${kind}</span>
        <h2 class="home-hero-title${cine?' cinelove-wordmark':''}">${safe(fullTitle)}</h2>
        <p class="home-hero-description">${slide.id==='noite-das-girls'?'Feito para Girls nada básicas: Harry Potter, Filmes de Terror, Crepúsculo e Animações Assustadoras. <strong class="night-bottom-line">Todos os pacotes mais diferentões em um só!</strong>':safe(slide.description)}</p>
        <div class="home-hero-actions">${cta}${arrows}</div>
      </div>${dots}
    </section>`;
  }
  
  function communityPanel(){return `<section class="community-panel community-panel--links-only community-icons-only" aria-label="Links do Clube das Girls"><div class="community-actions"><a class="community-link community-icon group" href="https://chat.whatsapp.com/KbXl2Ljvhdb4NPAMPjZdh0" target="_blank" rel="noopener noreferrer" aria-label="Entrar no grupo do WhatsApp" title="Entrar no grupo do WhatsApp"><svg class="shortcuts-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16 20v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="8.5" cy="7" r="4"/><path d="M22 20v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></svg></a><a class="community-link community-icon telegram" href="https://t.me/+sg6dmhX62mtjNzUx" target="_blank" rel="noopener noreferrer" aria-label="Acessar Telegram" title="Acessar Telegram">${I('send')}</a><a class="community-link community-icon support" href="https://wa.me/5521984598649" target="_blank" rel="noopener noreferrer" aria-label="Fale Conosco pelo WhatsApp" title="Fale Conosco pelo WhatsApp">${I('whatsapp')}</a></div></section>`}
  function tvTeaser(){return `<section class="promo promo-tv" aria-label="Como assistir na TV"><div class="promo-icon">${solidTvIcon()}</div><div class="promo-content promo-copy"><h3>Como assistir na TV?</h3><p>Aprenda a abrir o Cinema das Girls na Smart TV ou espelhar a tela com um passo a passo simples.</p></div><button class="secondary" data-action="nav" data-view="tvhelp">Ver tutorial ${I('chevron','sm')}</button></section>`}
  function homeShelf(id,heading,contents){return `<section class="cdg-home-shelf" aria-label="${heading}">
    <div class="cdg-shelf-heading">${title(heading,'explore')}<div class="cdg-shelf-controls" role="group" aria-label="Navegar cartazes de ${heading}">
      <button class="cdg-shelf-arrow" type="button" data-action="shelf-scroll" data-shelf="${id}" data-direction="-1" aria-label="Ver cartazes anteriores" disabled><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6"/></svg></button>
      <button class="cdg-shelf-arrow" type="button" data-action="shelf-scroll" data-shelf="${id}" data-direction="1" aria-label="Ver próximos cartazes"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg></button>
    </div></div><div class="cdg-shelf-track" data-shelf-track="${id}">${contents}</div>
    <p class="cdg-shelf-swipe-hint">Deslize para ver mais cartazes →</p></section>`}
  function updateShelfButtons(){
    document.querySelectorAll('#app [data-shelf-track]').forEach(wrapper=>{
      const strip=wrapper.querySelector('.universe-grid');if(!strip)return;
      const key=wrapper.dataset.shelfTrack;
      const before=document.querySelector('#app .cdg-shelf-arrow[data-shelf="'+key+'"][data-direction="-1"]');
      const after=document.querySelector('#app .cdg-shelf-arrow[data-shelf="'+key+'"][data-direction="1"]');
      if(before)before.disabled=strip.scrollLeft<=3;
      if(after)after.disabled=strip.scrollLeft+strip.clientWidth>=strip.scrollWidth-3;
    });
  }
  function scrollShelf(id,direction){
    const wrapper=Array.from(document.querySelectorAll('#app [data-shelf-track]')).find(node=>node.dataset.shelfTrack===id);
    const strip=wrapper?.querySelector('.universe-grid');if(!strip)return;
    const card=strip.querySelector('.universe-card');
    const gap=parseFloat(getComputedStyle(strip).columnGap)||0;
    const step=card ? card.getBoundingClientRect().width+gap : strip.clientWidth;
    const count=card?Math.max(1,Math.floor((strip.clientWidth+gap)/step)):1;
    strip.scrollBy({left:direction*step*count,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
  }
  document.addEventListener('scroll',event=>{if(event.target?.matches?.('#app .cdg-home-shelf .universe-grid'))updateShelfButtons()},true);
  window.addEventListener('resize',updateShelfButtons,{passive:true});
  function homeBarbieSeries(){return `<section class="cdg-home-barbie-series"><h3>Séries da Barbie</h3><div class="cdg-home-barbie-series-grid">${[{id:'life',title:'Barbie: Life in the Dreamhouse',cover:'assets/images/03/170-b128afbd9141.webp'},{id:'adventures',title:'Barbie Aventuras na Casa dos Sonhos',cover:'assets/images/03/168-069178cb616d.webp'}].map(item=>`<button type="button" class="cdg-home-series-card" data-action="home-barbie-series" data-series="${item.id}"><img src="${item.cover}" alt="Cartaz de ${item.title}" loading="lazy"><strong>${item.title}</strong></button>`).join('')}</div></section>`}
