    const seasonIndex=data.seasons.indexOf(chosen);
    const episodeIndex=currentEpisode&&currentEpisode.id===f.id&&currentEpisode.seasonIndex===seasonIndex&&chosen.items[currentEpisode.index]?currentEpisode.index:0;
