    const all=seriesItems(f.id);
    const absoluteIndex=all.findIndex(x=>x.seasonIndex===seasonIndex&&x.index===episodeIndex);
    const previous=all[absoluteIndex-1],next=all[absoluteIndex+1];
    const isPlaying=currentEpisode?.id===f.id&&currentEpisode.seasonIndex===seasonIndex&&currentEpisode.index===episodeIndex;
