  function openSeriesEpisode(seasonIndex,index){
    const id=active;
    if(!unlocked(id)&&id!=='bratz'){navigate('franchise');return;}
    const info=strawberrySeriesData(id);
    const season=info?.seasons?.[seasonIndex];
    const ep=season?.items?.[index];
    if(!ep)return;
    currentEpisode={id,seasonIndex,index};
    seriesSeason=season.name;
    try{SERIES_RECENT[strawberryRecentKey(id)]={title:ep.title,seasonIndex,index};localStorage.setItem(SERIES_PROGRESS,JSON.stringify(SERIES_RECENT))}catch{}
    const oldScroll=window.scrollY;
    render();
    window.scrollTo({top:oldScroll,behavior:'instant'});
  }
  function seriesStep(direction){
    const id=active;
    const list=seriesItems(id);
    const data=strawberrySeriesData(id);
    const seasonIndex=data?.seasons.findIndex(s=>s.name===(seriesSeason||data.seasons[0].name))||0;
    const index=currentEpisode&&currentEpisode.id===id&&currentEpisode.seasonIndex===seasonIndex?currentEpisode.index:0;
    const pos=list.findIndex(x=>x.seasonIndex===seasonIndex&&x.index===index);
    const target=list[pos+direction];
    if(target)openSeriesEpisode(target.seasonIndex,target.index);
  }

