  function openMySceneFilm(index){
    if(!unlocked('myscene')){active='myscene';catalogTab='Filmes';navigate('franchise');return;}
    const film=MYSCENE_FILMS[index];if(!film)return;
    if(film.embed){openPlayer(film.title,film.embed,'');return;}
    const modal=document.getElementById('playerModal');
    modal.querySelector('header strong').textContent=film.title;
    const hint=modal.querySelector('.player-hint');hint.textContent='';hint.style.display='none';
    const notice=document.createElement('div');notice.className='cdg-myscene-pending';
    const heading=document.createElement('h3');heading.textContent='Em breve';
    const message=document.createElement('p');message.textContent='O link de reprodução deste filme ainda será adicionado.';
    notice.append(heading,message);
    document.getElementById('playerHolder').replaceChildren(notice);
    modal.classList.add('open');document.body.style.overflow='hidden';
  }
