  function releasedCatalog(f,tab){
    if(f.id==='myscene'&&tab==='Filmes')return mysceneMovieCatalog();
    if(f.id==='moranguinho'&&tab==='Filmes')return `<div class="poster-grid">${moviePoster('Moranguinho: Doces Sonhos',STRAWBERRY_DREAMS_POSTER,'strawberry-dreams-play')}</div>`;
    if(f.id==='moranguinho'&&tab==='Séries')return (strawberryClassicOpen||strawberryTuttiOpen)
      ? `<button type="button" class="strawberry-series-back" data-action="strawberry-classic-back">${I('back','sm')} Voltar às séries</button>${seriesBrowser(f)}`
      : `<div class="poster-grid">${moviePoster('Moranguinho Clássica',STRAWBERRY_CLASSIC_POSTER,'strawberry-classic-open')}${moviePoster('Moranguinho: Aventuras em Tutti Frutti',STRAWBERRY_TUTTI_POSTER,'strawberry-tutti-open')}</div>`;
    if(f.id==='animacoes-assustadoras'&&tab==='Filmes')return `<div class="poster-grid">${ANIMACOES_ASSUSTADORAS_FILMS.map((film,index)=>moviePoster(film.title,film.cover,'animacoes-film',`data-index="${index}"`)).join('')}</div>`;
    if(f.id==='cinelove'&&tab==='Filmes')return cineLoveMoviesCatalog();
    if(f.id==='crepusculo'&&tab==='Filmes')return twilightMoviesCatalog();
    if(f.id==='crepusculo'&&tab==='Livros')return `<div class="poster-grid twilight-books-grid"><a class="poster-card twilight-book-card" href="https://drive.google.com/drive/folders/11jXzRexcIpsNDcj6wiUTHGS6ltA4DRe-?usp=sharing" target="_blank" rel="noopener noreferrer" aria-label="Abrir Saga Crepúsculo - Box de Livros no Google Drive"><span class="poster-cover"><img loading="lazy" src="assets/images/03/182-6f6bb4be7309.webp" alt="Capa Saga Crepúsculo - Box de Livros"><span class="poster-play">${I('play')}</span></span><strong>Saga Crepúsculo - Box de Livros</strong></a></div>`;
    if(f.id==='noite-das-girls')return `<div class="night-inside">${cards(['harry-potter','terror','crepusculo','animacoes-assustadoras'].map(el))}</div>`;
    if(f.id!=='barbie'&&tab==='Séries'&&SERIES[f.id])return ['espias','hello-kitty','bratz'].includes(f.id)?dreamhouseStyleSeriesBrowser(f):seriesBrowser(f);
    if(f.id!=='barbie'&&tab==='Especiais'&&SERIES[f.id])return ['espias','hello-kitty','bratz'].includes(f.id)?dreamhouseStyleSeriesBrowser(f):seriesBrowser(f);
    if(f.id==='terror'&&tab==='Filmes')return terrorMoviesCatalog();
    if(f.id==='harry-potter'&&tab==='Livros')return `<div class="poster-grid twilight-books-grid harry-books-grid"><a class="poster-card twilight-book-card harry-book-card" href="https://drive.google.com/drive/folders/1cq2nrgQ4hlDGs2SB-nBkgt8axJyFb5GO?usp=sharing" target="_blank" rel="noopener noreferrer" aria-label="Abrir Box de Livros da Saga Harry Potter no Google Drive"><span class="poster-cover"><img loading="lazy" src="assets/images/harry-potter/box-livros-harry-potter.webp" alt="Box de Livros da Saga Harry Potter"><span class="poster-play">${I('play')}</span></span><strong>Saga Harry Potter — Box de Livros</strong><small>Ver livros no Google Drive</small></a></div>`;
    if(f.id==='harry-potter'&&tab==='Filmes')return `<div class="poster-grid">${HARRY_POTTER_MOVIES.map((film,index)=>moviePoster(film.title,film.cover,'harry-potter-catalog-film',`data-index="${index}"`)).join('')}</div>`;
    if(f.id==='monster'&&tab==='Filmes')return `<div class="poster-grid">${contentMH.map(x=>moviePoster('Monster High: '+x.name,x.image)).join('')}</div><p class="catalog-disclaimer">Outros filmes de Monster High serão adicionados a esta seção conforme a atualização do catálogo.</p>`;
    if(f.id==='barbie'&&tab==='Especiais')return specialFilmCards(NEW_SPECIAL_FILMS.slice(1));
    if(f.id==='espias'&&tab==='Especiais')return specialFilmCards(NEW_SPECIAL_FILMS.slice(0,1));
    if(f.id==='barbie'&&tab==='Filmes')return barbieMoviesCatalog();
    if(f.id==='barbie'&&tab==='Séries')return barbieSeriesCatalog();
    if(f.id==='barbie'&&tab==='Jogos')return barbieGamesInline();
    return `<div class="catalog-empty">${I('film','big')}<h3>Catálogo em preparação</h3><p>${safe(tab)} de ${safe(f.name)} serão exibidos aqui com capas e botões de reprodução quando os conteúdos forem configurados.</p></div>`;
  }
  function purchasePage(){const f=el(active);const msg=encodeURIComponent('Olá! Quero garantir acesso ao pacote '+f.name+' do Cinema das Girls. Como faço para comprar?');return `<div class="page-wrap centred"><button class="back-button" style="display:flex" data-action="franchise" data-id="${f.id}">${I('back','sm')} Voltar</button><div class="section-panel"><img src="${f.art}" alt="${safe(f.name)}" style="width:145px;height:155px;object-fit:cover;border-radius:18px;margin:0 auto 16px;border:1px solid #f6bbda"><h1>${safe(f.name)}</h1><p class="page-subtitle">Garanta seu pacote e receba as instruções para acessar os conteúdos.</p><div class="price-line" style="margin-top:20px"><span>Pagamento único</span><strong>${f.price}</strong></div>${f.checkout?`<p class="page-subtitle" style="margin-bottom:19px">Pagamento único pela página de compra.</p><a class="primary block" href="${safe(f.checkout)}" target="_blank" rel="noopener noreferrer">${I('bag','sm')} Garantir acesso</a>`:`<p class="page-subtitle" style="margin-bottom:19px">Fale com nossa equipe pelo WhatsApp para saber como garantir o pacote.</p><a class="primary block" href="https://wa.me/5521984598649?text=${msg}" target="_blank" rel="noopener noreferrer">${I('whatsapp','sm')} Consultar acesso pelo WhatsApp</a>`}<button class="secondary" data-action="nav" data-view="redeem" style="width:100%;margin-top:11px">${I('unlock','sm')} Desbloquear pacote</button></div></div>`}

  function redeemPage(){return `<div class="centred"><button class="back-button" style="display:flex" data-action="nav" data-view="library">${I('back','sm')} Minha biblioteca</button><div class="section-panel"><div class="huge-icon">${I('lock','big')}</div><h1>Desbloquear pacote</h1><p class="page-subtitle">Digite o código que você recebeu após a compra.</p><form id="redeemForm"><input class="code-input" name="unlockCode" id="unlockCode" autocomplete="off" maxlength="40" placeholder="SEU CÓDIGO" value="${safe(redeemPrefill)}" aria-label="Código de acesso" required><button class="primary block" type="submit">${I('unlock','sm')} Desbloquear</button><p class="cdg-code-email-notice" role="note">Você recebe o código de desbloqueio por e-mail, não deixe de verificar a caixa de <strong>Spam!</strong></p></form></div></div>`}
  function favoriteTag(){return favoriteList.includes('Barbie – Live Action')?`<button class="secondary" data-action="favorite" data-title="Barbie – Live Action">${I('heart','sm')} Remover da lista</button>`:`<button class="secondary" data-action="favorite" data-title="Barbie – Live Action">${I('heart','sm')} Adicionar à minha lista</button>`}
  function favoritesPage(){return `<div class="page-wrap">${block('Minha lista','Guarde seus conteúdos favoritos para encontrar mais rápido.')}${favoriteList.length?`<div class="catalog-grid">${favoriteList.map(t=>`<div class="catalog-card"><img src="assets/images/03/167-d23172896e1d.webp" alt="Capa Barbie Live Action" style="object-fit:contain;background:#ffd1e8"><div class="description"><h3>${safe(t)}</h3><p>Salvo nos favoritos deste navegador</p><button class="primary small" data-action="play">${I('play','sm')} Assistir</button></div></div>`).join('')}</div>`:`<div class="empty-state">${I('heart','big')}<h3>Sua lista está vazia</h3><p>Toque no coração de um filme para adicioná-lo aqui.</p></div>`}</div>`}
