  const GAMES_PAGE_BASE64 = '';
  function gamesPage(){return `<div class="page-wrap" style="max-width:1160px;margin:auto;padding:12px 0 30px"><button class="back-button" type="button" data-action="nav" data-view="franchise">← Voltar à Barbie</button><div style="border-radius:22px;overflow:hidden;background:#fffafc;border:1px solid #f5d1e4;box-shadow:0 9px 24px #c5217720"><iframe id="gamesEmbedded" title="Jogos clássicos — Cinema das Girls" loading="eager" style="display:block;width:100%;height:85vh;min-height:620px;border:0;background:#fff9fc" sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-presentation"></iframe></div></div>`}
  function openEmbeddedGames(){
    const frame=document.getElementById('gamesEmbedded');
    if(!frame)return;
    // Decode only when games are opened, avoiding extra work on the home screen.
    try{
      const binary=atob(GAMES_PAGE_BASE64);
      const bytes=new Uint8Array(binary.length);
      for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
      frame.addEventListener('load',()=>{try{const doc=frame.contentDocument;const resize=()=>{const h=Math.max(doc.documentElement.scrollHeight,doc.body.scrollHeight);frame.style.height=Math.max(700,h+24)+'px'};resize();if(typeof ResizeObserver!=='undefined')new ResizeObserver(resize).observe(doc.body);setTimeout(resize,350);}catch(e){frame.style.height='2200px'}},{once:true});
      frame.srcdoc=new TextDecoder('utf-8').decode(bytes);
    }catch(error){
      frame.srcdoc='<html><body style="padding:28px;font-family:Arial;background:#fff0f8;color:#a91765"><h1>Jogos do Cinema das Girls</h1><p>Abra esta página em um navegador atualizado para iniciar os jogos.</p></body></html>';
    }
  }

  let heroRotationTimer;
  function restartHeroRotation(){
    clearInterval(heroRotationTimer);
    if(view!=='home'||selectedTab!=='Lançamentos'||search.trim()||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
    heroRotationTimer=setInterval(()=>{
      if(document.hidden||view!=='home'||selectedTab!=='Lançamentos'||search.trim())return;
      const displayed=app.querySelector('.home-uniform-hero');if(!displayed)return;
      heroIndex=(heroIndex+1)%homeHeroSlides.length;
      const holder=document.createElement('div');holder.innerHTML=heroMarkup();
      displayed.replaceWith(holder.firstElementChild);
    },15000);
  }
  let swipeStart=null;
  app.addEventListener('touchstart',event=>{if(event.target.closest('.home-uniform-hero')){const t=event.touches[0];swipeStart={x:t.clientX,y:t.clientY}}else swipeStart=null;},{passive:true});
  app.addEventListener('touchend',event=>{
    if(!swipeStart||!event.changedTouches.length)return;
    const t=event.changedTouches[0],dx=t.clientX-swipeStart.x,dy=t.clientY-swipeStart.y;swipeStart=null;
    if(Math.abs(dx)<45||Math.abs(dx)<Math.abs(dy)*1.25)return;
    heroIndex=(heroIndex+(dx<0?1:-1)+homeHeroSlides.length)%homeHeroSlides.length;
    const displayed=app.querySelector('.home-uniform-hero');if(displayed){const temp=document.createElement('div');temp.innerHTML=heroMarkup();displayed.replaceWith(temp.firstElementChild)}
    restartHeroRotation();
  },{passive:true});
  function render(){document.body.classList.toggle('locked-route',view==='franchise'&&!unlocked(active));document.body.classList.toggle('barbie-open',view==='franchise'&&active==='barbie'&&unlocked(active));let output;if(view==='home')output=homepage();else if(view==='explore')output=explorePage();else if(view==='library')output=libraryPage();else if(view==='franchise')output=franchisePage();else if(view==='purchase')output=purchasePage();else if(view==='redeem')output=redeemPage();else if(view==='favorites')output=favoritesPage();else if(view==='account')output=accountPage();else if(view==='tvhelp')output=tvHelpPage();else if(view==='games')output=gamesPage();else output=defaultHome();app.innerHTML=output;if(document.getElementById('gamesEmbedded'))openEmbeddedGames();document.querySelectorAll('#bottomNav .nav-item').forEach(item=>item.classList.toggle('active',item.dataset.view===(view==='franchise'||view==='purchase'?'explore':view==='redeem'?'library':view==='favorites'||view==='tvhelp'?'account':view)));document.querySelectorAll('.top-nav-link[data-view]').forEach(item=>{const activeView=(view==='franchise'||view==='purchase')?'explore':view;item.classList.toggle('is-active',item.dataset.view===activeView);if(item.dataset.view===activeView){item.setAttribute('aria-current','page')}else{item.removeAttribute('aria-current')}});saveAccess();restartHeroRotation();requestAnimationFrame(updateShelfButtons)}
  function navigate(next,skipScroll=false){view=next;search='';if(view==='home')selectedTab='Lançamentos';if(view==='franchise'&&active==='barbie')heroIndex=0;closeDrawer();render();if(!skipScroll)window.scrollTo({top:0,behavior:'instant'})}
  function closeDrawer(){document.getElementById('drawer').classList.remove('open');document.getElementById('drawerOverlay').classList.remove('open')}
  function openBarbieMovie(index){
    if(!unlocked('barbie')){active='barbie';navigate('franchise');return}
    const movie=BARBIE_FILMS[index];if(!movie)return;
    const dialog=document.getElementById('playerModal');
    dialog.querySelector('header strong').textContent=movie.title+' ('+movie.year+')';
    dialog.querySelector('.player-hint').style.display='';
    if(!movie.embed){
      dialog.querySelector('.player-hint').textContent='O link de reprodução deste lançamento ainda será adicionado.';
      const placeholder=document.createElement('div');
      placeholder.className='barbie-nut-player-pending';
      const cover=document.createElement('img');cover.src=movie.cover;cover.alt='Capa de '+movie.title;
      const message=document.createElement('div');message.innerHTML='<span class="barbie-nut-player-badge">NOVIDADE</span><h3>Barbie Quebra-nozes</h3><p>O player está preparado. O vídeo será liberado assim que o link de reprodução for adicionado.</p>';
      placeholder.append(cover,message);
      document.getElementById('playerHolder').replaceChildren(placeholder);
    } else {
      const isDrive=movie.embed.includes('drive.google.com');
      dialog.querySelector('.player-hint').textContent='';
      dialog.querySelector('.player-hint').style.display='none';
      const frame=document.createElement('iframe');
      frame.title=movie.title;frame.src=movie.embed;frame.allow='autoplay;fullscreen;picture-in-picture';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';
      document.getElementById('playerHolder').replaceChildren(frame);
    }
    dialog.classList.add('open');document.body.style.overflow='hidden';
  }
  function openPlayer(title, url, hint){
    if(title && url){
      currentEpisode=null;
      const modal=document.getElementById('playerModal');
      modal.querySelector('header strong').textContent=title;
      const hintEl=modal.querySelector('.player-hint');
      hintEl.textContent=hint||'';
      hintEl.style.display=(hint&&String(hint).trim())?'':'none';
      const frame=document.createElement('iframe');
      frame.title=title;
      frame.src=url;
      frame.allow='autoplay; fullscreen; picture-in-picture';
      frame.allowFullscreen=true;
      frame.referrerPolicy='strict-origin-when-cross-origin';
      document.getElementById('playerHolder').replaceChildren(frame);
      modal.classList.add('open');
      document.body.style.overflow='hidden';
      return;
    }
    currentEpisode=null;document.querySelector('#playerModal header strong').textContent='Barbie – Live Action (2023)';const liveHint=document.querySelector('#playerModal .player-hint');liveHint.textContent='';liveHint.style.display='none';if(!unlocked('barbie')){active='barbie';navigate('franchise');toast('Desbloqueie Barbie para assistir.');return}document.getElementById('playerHolder').innerHTML='<iframe title="Barbie Live Action – Tokyvideo" src="https://www.tokyvideo.com/br/embed/742622" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>';document.getElementById('playerModal').classList.add('open');document.body.style.overflow='hidden'}
  function closePlayer(){document.getElementById('playerHolder').innerHTML='';document.getElementById('playerModal').classList.remove('open');document.body.style.overflow=''}
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&document.getElementById('playerModal').classList.contains('open')){closePlayer();}});
  function toggleFavorite(name){if(favoriteList.includes(name)){favoriteList=favoriteList.filter(x=>x!==name);toast('Removido da sua lista.')}else{favoriteList.push(name);toast('Adicionado à sua lista!')}saveFav();render()}
