    if(act==='monster-season-step'){monsterSeasonIndex=Math.max(0,Math.min(5,monsterSeasonIndex+(Number(b.dataset.step)||0)));monsterSeasonPlaying=true;const y=window.scrollY;render();window.scrollTo(0,y);return}
    if(act==='monster-ghoul-watch'||act==='monster-ghoul-episode'){const episode=Math.min(10,Math.max(1,Number(b.dataset.episode)||1));openPlayer('Monster High: Aventuras do Esquadrão Monstro — T1 E'+episode, 'https://playlistplus.online/play/?serie=Monster%20High%3A%20Aventuras%20do%20Esquadr%C3%A3o%20Monstro&s=1&e='+episode, '');return}
