  function redeemAnyCode(raw){
    const code=(raw||'').trim().toUpperCase().replace(/[\s-]/g,'');
    const series=Object.keys(BARBIE_SERIES_CODES).find(id=>BARBIE_SERIES_CODES[id]===code);
    const found=Object.keys(DEMO_CODES).find(id=>DEMO_CODES[id]===code);
    if(!found&&!series)return null;
    if(found){access[found]=true;if(found==='noite-das-girls')['harry-potter','crepusculo','terror','animacoes-assustadoras'].forEach(id=>access[id]=true);}
    if(series&&series!=='myscene')barbieSeriesAccess[series]=true;
    if(found==='barbie-dreamhouse')barbieSeriesAccess.life=true;
    if(series==='myscene')access.myscene=true;
    saveAccess();
    try{localStorage.setItem(BARBIE_SERIES_ACCESS_KEY,JSON.stringify(barbieSeriesAccess))}catch(e){}
    return {found,series};
  }
  document.addEventListener('submit',event=>{
    if(event.target.id!=='barbieSeriesUnlockForm')return;
    event.preventDefault();
    const id=event.target.elements.series.value;
    const entered=(event.target.elements.code.value||'').trim().toUpperCase().replace(/[\s-]/g,'');
    const result=redeemAnyCode(entered);
    if(!result){toast('Código inválido. Confira e tente novamente.');return;}
    if(result.series===id||(id==='life'&&result.found==='barbie-dreamhouse')){render();toast('Série desbloqueada neste navegador!');return;}
    if(result.found&&franchises.some(f=>f.id===result.found)){active=result.found;navigate('franchise');toast(el(result.found).name+' liberado neste navegador!');return;}
    barbieSeriesView=result.series||'gallery';active='barbie';navigate('franchise');toast('Código aceito! Pacote correspondente liberado.');
  });
  document.addEventListener('submit',event=>{if(event.target.id!=='redeemForm')return;event.preventDefault();const result=redeemAnyCode(event.target.elements.unlockCode.value);if(!result){toast('Código não encontrado. Confira e tente novamente.');return;}redeemPrefill='';if(result.found&&franchises.some(f=>f.id===result.found)){active=result.found;navigate('franchise');toast(el(result.found).name+' liberado neste navegador!');return;}active='barbie';barbieSeriesView=result.series||'gallery';navigate('franchise');toast('Série liberada neste navegador!');});
  document.addEventListener('input',event=>{if(event.target.id==='search'){search=event.target.value;const start=event.target.selectionStart;render();const box=document.getElementById('search');if(box){box.focus();box.setSelectionRange(start,start)}}else if(event.target.id==='unlockCode'){redeemPrefill=event.target.value}});
